import { Router } from 'express';
import rateLimit from 'express-rate-limit';
import bcrypt from 'bcryptjs';
import crypto from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { query, pool } from './db.js';
import { authenticate, allow, signToken } from './auth.js';
import { asyncRoute, haversine, priceFor } from './util.js';
import { emitBooking, emitUser } from './realtime.js';
export const router = Router();
const privateDocumentRoot = path.resolve(process.env.EQUIPMENT_DOCUMENT_DIR || path.join(path.dirname(fileURLToPath(import.meta.url)), '../uploads/private'));
const allowedDocuments = { 'application/pdf': 'pdf', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
router.use('/auth', rateLimit({ windowMs: 15 * 60 * 1000, limit: 80, standardHeaders: true, legacyHeaders: false }));
const roles = ['FARMER','OWNER','ADMIN'];
const equipmentTypes = ['Tractor','Harvester','Transportation','Rotavator','Cultivator','Seeder','Plough','Sprayer','Thresher','Land Leveller','Other'];
function validCoords(lat, lng) { return Number.isFinite(+lat) && Number.isFinite(+lng) && +lat >= -90 && +lat <= 90 && +lng >= -180 && +lng <= 180; }
function validPhone(phone) { const value=String(phone||'').trim(),digits=value.replace(/\D/g,'');return /^\+?[0-9][0-9\s().-]{5,22}$/.test(value)&&digits.length>=7&&digits.length<=15; }
function validTime(value) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(value || '')); }
async function notify(user, booking, type, title, message) { const result = await query('INSERT INTO notifications(user_id,booking_id,notification_type,title,message) VALUES(?,?,?,?,?)',[user,booking,type,title,message]); const item={id:result.insertId,user_id:user,booking_id:booking,notification_type:type,title,message,is_read:0,created_at:new Date()}; emitUser(user,'new_notification',item); }
async function bookingFor(id,user) { const rows=await query('SELECT b.*,e.brand,e.model,e.equipment_type,s.name service_name,f.name field_name,f.latitude field_latitude,f.longitude field_longitude,f.area_acres field_area,farmer.name farmer_name,farmer.phone farmer_phone,owner.name owner_name,owner.phone owner_phone,e.registration_number FROM bookings b JOIN equipment e ON e.id=b.equipment_id JOIN services s ON s.id=b.service_id LEFT JOIN fields f ON f.id=b.field_id JOIN users farmer ON farmer.id=b.farmer_id JOIN users owner ON owner.id=b.owner_id WHERE b.id=?',[id]); const b=rows[0]; if(!b) throw Object.assign(new Error('Booking not found.'),{status:404}); if(user.role!=='ADMIN'&&user.id!==b.farmer_id&&user.id!==b.owner_id) throw Object.assign(new Error('You cannot access this booking.'),{status:403}); if(user.role==='FARMER'&&['REQUESTED','REJECTED','CANCELLED'].includes(b.status)){delete b.owner_phone;delete b.registration_number;delete b.driver_name;delete b.driver_phone;} if(user.role==='OWNER'&&b.status==='REQUESTED'){delete b.farmer_phone;delete b.field_latitude;delete b.field_longitude;delete b.field_name;} return b; }
router.post('/bookings',authenticate,allow('FARMER'),asyncRoute(async(req,res)=>{
 const d=req.body,quantity=Number(d.quantity);
 if(!d.equipment_id||!d.service_id||!d.field_id||!/^\d{4}-\d{2}-\d{2}$/.test(String(d.booking_date||''))||!validTime(d.start_time)||!validTime(d.end_time)||String(d.end_time)<=String(d.start_time)||!Number.isFinite(quantity)||quantity<=0)return res.status(400).json({error:'Choose a saved field, valid date, start and end time, and positive quantity.'});
 const dateCheck=(await query('SELECT (? > CURDATE() OR (? = CURDATE() AND ? > CURTIME())) AS valid_date',[d.booking_date,d.booking_date,d.start_time]))[0];
 if(!dateCheck.valid_date)return res.status(400).json({error:'Choose a future date and time.'});
 const eq=(await query("SELECT e.*,es.pricing_model,es.price,es.minimum_quantity FROM equipment e JOIN equipment_services es ON es.equipment_id=e.id WHERE e.id=? AND es.service_id=? AND e.verification_status='VERIFIED' AND e.availability_status='AVAILABLE'",[d.equipment_id,d.service_id]))[0];
 if(!eq)return res.status(404).json({error:'Verified available equipment or service was not found.'});
 if(quantity<eq.minimum_quantity)return res.status(400).json({error:`Minimum quantity is ${eq.minimum_quantity}.`});
 const field=(await query('SELECT id,area_acres FROM fields WHERE id=? AND farmer_id=?',[d.field_id,req.user.id]))[0];
 if(!field)return res.status(403).json({error:'Select one of your saved fields.'});
 if(eq.pricing_model==='PER_ACRE'&&quantity>Number(field.area_acres))return res.status(400).json({error:`Quantity cannot exceed the saved field size of ${field.area_acres} acres.`});
 const slot=(await query("SELECT id FROM availability WHERE equipment_id=? AND available_date=? AND status='AVAILABLE' AND start_time<=? AND end_time>=? LIMIT 1",[d.equipment_id,d.booking_date,d.start_time,d.end_time]))[0];
 if(!slot)return res.status(409).json({error:'That time is outside the owner’s published availability. Choose a listed date and time.'});
 const clash=await query("SELECT id FROM bookings WHERE equipment_id=? AND booking_date=? AND status IN ('REQUESTED','ACCEPTED','OWNER_EN_ROUTE','ARRIVED','SERVICE_STARTED','PAYMENT_PENDING') AND start_time<? AND end_time>? LIMIT 1",[d.equipment_id,d.booking_date,d.end_time,d.start_time]);
 if(clash.length)return res.status(409).json({error:'That time overlaps another booking. Choose another time.'});
 const duration=(time=>{const [h,m]=String(time).split(':').map(Number);return h*60+m;})(d.end_time)-((time=>{const [h,m]=String(time).split(':').map(Number);return h*60+m;})(d.start_time));
 const amount=priceFor(eq.pricing_model,eq.price,quantity);
 const r=await query('INSERT INTO bookings(farmer_id,owner_id,equipment_id,service_id,field_id,booking_date,start_time,end_time,duration,quantity,pricing_model,base_price,estimated_amount,final_amount,farmer_notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[req.user.id,eq.owner_id,d.equipment_id,d.service_id,d.field_id,d.booking_date,d.start_time,d.end_time,duration/60,quantity,eq.pricing_model,eq.price,amount,amount,d.farmer_notes||null]);
 await notify(eq.owner_id,r.insertId,'booking_requested','New booking request',`A farmer requested ${eq.brand} ${eq.model}.`);
 emitBooking(r.insertId,'booking_requested',{booking_id:r.insertId});
 res.status(201).json({id:r.insertId,status:'REQUESTED',estimated_amount:amount,pricing_model:eq.pricing_model});
}));
router.post('/auth/register',asyncRoute(async(req,res)=>{const {name,phone,email,password,role='FARMER',village,latitude,longitude}=req.body;if(!name||!phone||!email||!password||password.length<8||!roles.includes(role)||role==='ADMIN'||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return res.status(400).json({error:'Enter valid account details. Password must be at least 8 characters.'});if((latitude!=null||longitude!=null)&&!validCoords(latitude,longitude))return res.status(400).json({error:'Enter valid coordinates.'});const hash=await bcrypt.hash(password,12);try{const r=await query('INSERT INTO users(name,phone,email,password_hash,role,village,latitude,longitude) VALUES(?,?,?,?,?,?,?,?)',[name.trim(),phone.trim(),email.toLowerCase().trim(),hash,role,village||null,latitude||null,longitude||null]);const user={id:r.insertId,name,phone,email,role,village};res.status(201).json({user,token:signToken(user)});}catch(e){if(e.code==='ER_DUP_ENTRY')return res.status(409).json({error:'An account with that email already exists.'});throw e;}}));
router.post('/auth/login',asyncRoute(async(req,res)=>{const rows=await query('SELECT id,name,phone,email,password_hash,role,village FROM users WHERE email=? AND is_active=1',[String(req.body.email||'').toLowerCase().trim()]);if(!rows[0]||!await bcrypt.compare(req.body.password||'',rows[0].password_hash))return res.status(401).json({error:'Email or password is incorrect.'});const {password_hash,...user}=rows[0];res.json({user,token:signToken(user)});}));
router.get('/auth/me',authenticate,asyncRoute(async(req,res)=>{const rows=await query('SELECT id,name,phone,email,role,village,latitude,longitude,created_at FROM users WHERE id=?',[req.user.id]);if(!rows[0])return res.status(404).json({error:'Account not found.'});res.json({user:rows[0]});}));
router.post('/auth/forgot-password',asyncRoute(async(req,res)=>{const rows=await query('SELECT id,email FROM users WHERE email=?',[String(req.body.email||'').toLowerCase().trim()]);if(!rows[0])return res.json({message:'If the account exists, password recovery is available.'});const token=crypto.randomBytes(32).toString('hex'),hash=crypto.createHash('sha256').update(token).digest('hex');await query('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))',[rows[0].id,hash]);const data={message:'Password reset token created. No email has been sent.'};if(process.env.NODE_ENV!=='production')data.resetToken=token;res.json(data);}));
router.post('/auth/reset-password',asyncRoute(async(req,res)=>{const {token,password}=req.body;if(!token||!password||password.length<8)return res.status(400).json({error:'Provide a valid reset token and a password of at least 8 characters.'});const hash=crypto.createHash('sha256').update(token).digest('hex'),rows=await query('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used=0 AND expires_at>NOW()',[hash]);if(!rows[0])return res.status(400).json({error:'This reset token is invalid or expired.'});const conn=await pool.getConnection();try{await conn.beginTransaction();await conn.execute('UPDATE users SET password_hash=? WHERE id=?',[await bcrypt.hash(password,12),rows[0].user_id]);await conn.execute('UPDATE password_reset_tokens SET used=1 WHERE id=?',[rows[0].id]);await conn.commit();res.json({message:'Password updated. Please sign in.'});}catch(e){await conn.rollback();throw e;}finally{conn.release();}}));
router.get('/services',asyncRoute(async(req,res)=>res.json(await query('SELECT * FROM services ORDER BY name'))));
router.get('/owner/equipment',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>res.json(await query('SELECT * FROM equipment WHERE owner_id=? ORDER BY created_at DESC',[req.user.id]))));
router.get('/owner/equipment/:id([0-9]+)/services',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const owned=(await query('SELECT id FROM equipment WHERE id=? AND owner_id=?',[req.params.id,req.user.id]))[0];if(!owned)return res.status(404).json({error:'Equipment listing not found.'});res.json(await query('SELECT es.*,s.name service_name FROM equipment_services es JOIN services s ON s.id=es.service_id WHERE es.equipment_id=? ORDER BY s.name',[req.params.id]));}));
router.get('/availability',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>res.json(await query('SELECT a.*,e.brand,e.model FROM availability a JOIN equipment e ON e.id=a.equipment_id WHERE e.owner_id=? ORDER BY a.available_date',[req.user.id]))));
router.post('/availability',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const d=req.body,e=(await query('SELECT id FROM equipment WHERE id=? AND owner_id=?',[d.equipment_id,req.user.id]))[0];if(!e)return res.status(403).json({error:'Choose your own equipment.'});if(!/^\d{4}-\d{2}-\d{2}$/.test(String(d.available_date||''))||!validTime(d.start_time)||!validTime(d.end_time)||d.start_time>=d.end_time)return res.status(400).json({error:'Enter a valid date and time range.'});const date=(await query('SELECT ? >= CURDATE() AS valid_date',[d.available_date]))[0];if(!date.valid_date)return res.status(400).json({error:'Availability must be today or a future date.'});const overlaps=await query("SELECT id FROM availability WHERE equipment_id=? AND available_date=? AND start_time<>? AND status='AVAILABLE' AND start_time<? AND end_time>? LIMIT 1",[d.equipment_id,d.available_date,d.start_time,d.end_time,d.start_time]);if(overlaps.length)return res.status(409).json({error:'This availability overlaps another published time for the equipment.'});const r=await query("INSERT INTO availability(equipment_id,available_date,start_time,end_time,status) VALUES(?,?,?,?, 'AVAILABLE') ON DUPLICATE KEY UPDATE end_time=VALUES(end_time),status='AVAILABLE'",[d.equipment_id,d.available_date,d.start_time,d.end_time]);res.status(201).json({id:r.insertId||true});}));
router.delete('/availability/:id',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const r=await query('DELETE a FROM availability a JOIN equipment e ON e.id=a.equipment_id WHERE a.id=? AND e.owner_id=?',[req.params.id,req.user.id]);res.json({deleted:r.affectedRows>0});}));
router.get('/equipment',asyncRoute(async(req,res)=>{let sql=`SELECT e.*,u.name owner_name, (SELECT AVG(r.rating) FROM reviews r WHERE r.reviewed_user_id=e.owner_id) rating,(SELECT COUNT(*) FROM reviews r WHERE r.reviewed_user_id=e.owner_id) review_count FROM equipment e JOIN users u ON u.id=e.owner_id WHERE e.verification_status='VERIFIED'`;const args=[];if(req.query.type){sql+=' AND e.equipment_type=?';args.push(req.query.type);}if(req.query.lat&&req.query.lng&&validCoords(req.query.lat,req.query.lng)){const all=await query(sql,args);const data=all.map(e=>({...e,distance_km:+haversine(+req.query.lat,+req.query.lng,+e.latitude,+e.longitude).toFixed(1)})).filter(e=>!req.query.maxDistance||e.distance_km<=+req.query.maxDistance).sort((a,b)=>a.distance_km-b.distance_km);return res.json(data);}res.json(await query(sql+' ORDER BY e.created_at DESC LIMIT 100',args));}));
router.get('/equipment/nearby',authenticate,allow('FARMER'),asyncRoute(async(req,res)=>{const {lat,lng}=req.query;if(!validCoords(lat,lng))return res.status(400).json({error:'Select your location before searching for equipment.'});let sql="SELECT e.*,u.name owner_name,(SELECT AVG(r.rating) FROM reviews r WHERE r.reviewed_user_id=e.owner_id) rating,(SELECT COUNT(*) FROM reviews r WHERE r.reviewed_user_id=e.owner_id) review_count FROM equipment e JOIN users u ON u.id=e.owner_id WHERE e.verification_status='VERIFIED' AND e.availability_status='AVAILABLE'",args=[];if(req.query.type){sql+=' AND e.equipment_type=?';args.push(req.query.type)}const all=await query(sql,args),list=all.map(e=>({...e,distance_km:+haversine(+lat,+lng,+e.latitude,+e.longitude).toFixed(1)})).filter(e=>!req.query.maxDistance||e.distance_km<=+req.query.maxDistance);for(const e of list){e.services=await query('SELECT es.*,s.name service_name FROM equipment_services es JOIN services s ON s.id=es.service_id WHERE es.equipment_id=?',[e.id]);const prices=e.services.filter(s=>s.pricing_model!=='QUOTE').map(s=>Number(s.price)).filter(Number.isFinite);e.starting_price=prices.length?Math.min(...prices):null}if(req.query.sort==='price')list.sort((a,b)=>a.starting_price==null?1:b.starting_price==null?-1:a.starting_price-b.starting_price||a.distance_km-b.distance_km);else if(req.query.sort==='rating')list.sort((a,b)=>(b.rating||0)-(a.rating||0)||a.distance_km-b.distance_km);else list.sort((a,b)=>a.distance_km-b.distance_km);res.json(list)}));
router.get('/equipment/:id([0-9]+)/availability',asyncRoute(async(req,res)=>{const equipment=(await query("SELECT id FROM equipment WHERE id=? AND verification_status='VERIFIED' AND availability_status='AVAILABLE'",[req.params.id]))[0];if(!equipment)return res.status(404).json({error:'Equipment not found.'});if(req.query.date&&!/^\d{4}-\d{2}-\d{2}$/.test(String(req.query.date)))return res.status(400).json({error:'Choose a valid date.'});res.json(await query("SELECT available_date,start_time,end_time FROM availability WHERE equipment_id=? AND status='AVAILABLE' AND available_date>=CURDATE() AND (?='' OR available_date=?) ORDER BY available_date,start_time",[req.params.id,req.query.date||'',req.query.date||'']));}));
router.get('/equipment/:id([0-9]+)',asyncRoute(async(req,res)=>{const rows=await query(`SELECT e.*,u.name owner_name,(SELECT AVG(r.rating) FROM reviews r WHERE r.reviewed_user_id=e.owner_id) rating,(SELECT COUNT(*) FROM reviews r WHERE r.reviewed_user_id=e.owner_id) review_count FROM equipment e JOIN users u ON u.id=e.owner_id WHERE e.id=? AND e.verification_status='VERIFIED'`,[req.params.id]);if(!rows[0])return res.status(404).json({error:'Equipment not found.'});rows[0].services=await query('SELECT es.*,s.name service_name FROM equipment_services es JOIN services s ON s.id=es.service_id WHERE es.equipment_id=?',[req.params.id]);res.json(rows[0]);}));
router.post('/equipment',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const d=req.body;if(!d.equipment_type||!d.brand||!d.model||!String(d.registration_number||'').trim()||!validCoords(d.latitude,d.longitude))return res.status(400).json({error:'Enter the equipment type, brand, model, registration number, and valid location.'});try{const r=await query(`INSERT INTO equipment(owner_id,equipment_type,brand,model,registration_number,year,hp_or_capacity,description,latitude,longitude,village) VALUES(?,?,?,?,?,?,?,?,?,?,?)`,[req.user.id,d.equipment_type,d.brand,d.model,d.registration_number||null,d.year||null,d.hp_or_capacity||null,d.description||null,d.latitude,d.longitude,d.village||null]);res.status(201).json({id:r.insertId,verification_status:'PENDING_VERIFICATION'});}catch(e){if(e.code==='ER_DUP_ENTRY')return res.status(409).json({error:'That registration number is already listed.'});throw e;}}));
router.post('/equipment/:id([0-9]+)/documents',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{
 const equipment=(await query('SELECT id FROM equipment WHERE id=? AND owner_id=?',[req.params.id,req.user.id]))[0];
 if(!equipment)return res.status(404).json({error:'Equipment listing not found.'});
 const {document_type,mime_type,original_name,data_base64}=req.body;
 if(!['REGISTRATION_CERTIFICATE','INSURANCE','OWNER_ID','OTHER'].includes(document_type)||!allowedDocuments[mime_type]||typeof data_base64!=='string')return res.status(400).json({error:'Choose a supported verification document (PDF, JPEG, PNG, or WebP).'});
 const encoded=data_base64.replace(/^data:[^;]+;base64,/,'');
 if(!/^[A-Za-z0-9+/]*={0,2}$/.test(encoded))return res.status(400).json({error:'The uploaded document is not valid base64 data.'});
 const contents=Buffer.from(encoded,'base64');
 if(!contents.length||contents.length>5*1024*1024)return res.status(413).json({error:'Each document must be smaller than 5 MB.'});
 const signatureOk=mime_type==='application/pdf'?contents.subarray(0,5).toString()==='%PDF-':mime_type==='image/jpeg'?contents[0]===0xff&&contents[1]===0xd8:mime_type==='image/png'?contents.subarray(0,8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a])):contents.subarray(0,4).toString()==='RIFF'&&contents.subarray(8,12).toString()==='WEBP';
 if(!signatureOk)return res.status(400).json({error:'The file contents do not match the selected document type.'});
 const safeName=path.basename(String(original_name||`document.${allowedDocuments[mime_type]}`)).replace(/[\r\n\0]/g,'').slice(0,255);
 const storageKey=`${req.params.id}/${crypto.randomUUID()}.${allowedDocuments[mime_type]}`;
 const filePath=path.resolve(privateDocumentRoot,storageKey);
 if(!filePath.startsWith(`${privateDocumentRoot}${path.sep}`))return res.status(400).json({error:'Invalid document path.'});
 await mkdir(path.dirname(filePath),{recursive:true});
 await writeFile(filePath,contents,{flag:'wx'});
 let result;
 try { result=await query('INSERT INTO equipment_documents(equipment_id,document_type,storage_key,original_name) VALUES(?,?,?,?)',[req.params.id,document_type,storageKey,safeName]); }
 catch(error) { await rm(filePath,{force:true}); throw error; }
 if(document_type==='REGISTRATION_CERTIFICATE')await query("UPDATE equipment SET verification_status='PENDING_VERIFICATION',registration_status='PENDING_VERIFICATION' WHERE id=?",[req.params.id]);
 res.status(201).json({id:result.insertId,equipment_id:+req.params.id,document_type,original_name:safeName});
}));
router.get('/owner/equipment/:id([0-9]+)/documents',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{
 const equipment=(await query('SELECT id FROM equipment WHERE id=? AND owner_id=?',[req.params.id,req.user.id]))[0];
 if(!equipment)return res.status(404).json({error:'Equipment listing not found.'});
 res.json(await query('SELECT id,equipment_id,document_type,original_name,uploaded_at FROM equipment_documents WHERE equipment_id=? ORDER BY uploaded_at DESC',[req.params.id]));
}));
router.put('/equipment/:id',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const d=req.body;if(!d.brand||!d.model||!String(d.registration_number||'').trim()||!equipmentTypes.includes(d.equipment_type)||!validCoords(d.latitude,d.longitude))return res.status(400).json({error:'Enter a valid equipment type, brand, model, registration number, and location.'});const existing=(await query('SELECT registration_number FROM equipment WHERE id=? AND owner_id=?',[req.params.id,req.user.id]))[0];if(!existing)return res.status(404).json({error:'Equipment listing not found.'});const registration=String(d.registration_number||'').trim()||null,changed=String(existing.registration_number||'')!==String(registration||'');try{await query('UPDATE equipment SET brand=?,model=?,equipment_type=?,registration_number=?,description=?,village=?,latitude=?,longitude=?,hp_or_capacity=?,year=?,registration_status=IF(?=1,IF(? IS NULL,\'NOT_REQUIRED\',\'PENDING_VERIFICATION\'),registration_status),verification_status=IF(?=1,\'PENDING_VERIFICATION\',verification_status) WHERE id=? AND owner_id=?',[d.brand.trim(),d.model.trim(),d.equipment_type,registration,d.description||null,d.village||null,d.latitude,d.longitude,d.hp_or_capacity||null,d.year||null,changed?1:0,registration,changed?1:0,req.params.id,req.user.id]);res.json({updated:true,verification_status:changed?'PENDING_VERIFICATION':undefined});}catch(e){if(e.code==='ER_DUP_ENTRY')return res.status(409).json({error:'That registration number is already listed.'});throw e;}}));
router.delete('/equipment/:id',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const r=await query('DELETE FROM equipment WHERE id=? AND owner_id=?',[req.params.id,req.user.id]);res.json({deleted:r.affectedRows>0});}));
router.patch('/equipment/:id/availability-status',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{if(!['AVAILABLE','UNAVAILABLE'].includes(req.body.status))return res.status(400).json({error:'Choose AVAILABLE or UNAVAILABLE.'});const r=await query('UPDATE equipment SET availability_status=? WHERE id=? AND owner_id=?',[req.body.status,req.params.id,req.user.id]);if(!r.affectedRows)return res.status(404).json({error:'Equipment listing not found.'});res.json({availability_status:req.body.status});}));
router.post('/equipment/:id/services',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const owned=(await query('SELECT id FROM equipment WHERE id=? AND owner_id=?',[req.params.id,req.user.id]))[0];if(!owned)return res.status(404).json({error:'Equipment listing not found.'});const {service_id,pricing_model,price,minimum_quantity=1,description}=req.body,amount=Number(price),minimum=Number(minimum_quantity);if(!service_id||!['PER_ACRE','PER_HOUR','PER_TRIP','FIXED','QUOTE'].includes(pricing_model)||!Number.isFinite(amount)||amount<0||!Number.isFinite(minimum)||minimum<=0)return res.status(400).json({error:'Enter a valid service, pricing model, price, and minimum quantity.'});try{const r=await query('INSERT INTO equipment_services(equipment_id,service_id,pricing_model,price,minimum_quantity,description) VALUES(?,?,?,?,?,?)',[req.params.id,service_id,pricing_model,amount,minimum,description||null]);res.status(201).json({id:r.insertId});}catch(e){if(e.code==='ER_DUP_ENTRY')return res.status(409).json({error:'This service is already listed for this equipment.'});throw e;}}));
