router.patch('/bookings/:id/accept',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{
 const b=await bookingFor(req.params.id,req.user);
 if(b.owner_id!==req.user.id)return res.status(403).json({error:'You cannot accept this booking.'});
 if(b.status!=='REQUESTED')return res.status(409).json({error:`This action is not available while booking is ${b.status}.`});
 const conflict=await query("SELECT id FROM bookings WHERE equipment_id=? AND id<>? AND booking_date=? AND status IN ('ACCEPTED','OWNER_EN_ROUTE','ARRIVED','SERVICE_STARTED','PAYMENT_PENDING') AND start_time<? AND end_time>? LIMIT 1",[b.equipment_id,b.id,b.booking_date,b.end_time,b.start_time]);
 if(conflict.length)return res.status(409).json({error:'This time now overlaps another accepted booking.'});
 const operatorType=String(req.body.operator_type||'').toUpperCase();
 if(!['OWNER','DRIVER'].includes(operatorType))return res.status(400).json({error:'Choose whether you or a driver will perform the service.'});
 const driverName=String(req.body.driver_name||'').trim(),driverPhone=String(req.body.driver_phone||'').trim();
 if(operatorType==='DRIVER'&&(!driverName||driverName.length>120||!validPhone(driverPhone)))return res.status(400).json({error:'Enter the driver full name and a valid phone number before accepting.'});
 const quoteAmount=b.pricing_model==='QUOTE'?Number(req.body.final_amount):Number(b.final_amount??b.estimated_amount);
 if(!Number.isFinite(quoteAmount)||quoteAmount<=0)return res.status(400).json({error:b.pricing_model==='QUOTE'?'Enter the amount you are quoting before accepting.':'This booking has no valid amount.'});
 const update=await query("UPDATE bookings SET status='ACCEPTED',operator_type=?,driver_name=?,driver_phone=?,final_amount=? WHERE id=? AND owner_id=? AND status='REQUESTED'",[operatorType,operatorType==='DRIVER'?driverName:null,operatorType==='DRIVER'?driverPhone:null,quoteAmount,req.params.id,req.user.id]);
 if(!update.affectedRows)return res.status(409).json({error:'This booking was updated already. Refresh and review it again.'});
 await query('INSERT IGNORE INTO service_sessions(booking_id,owner_id) VALUES(?,?)',[req.params.id,req.user.id]);
 const assigned=operatorType==='DRIVER'?`Assigned driver: ${driverName} · ${driverPhone}.`:`Assigned operator: ${b.owner_name} · ${b.owner_phone}.`;
 const quote=`Final quoted amount: ₹${quoteAmount.toFixed(2)}.`;
 await notify(b.farmer_id,req.params.id,'booking_accepted','Booking accepted',`Your booking was accepted. ${assigned} ${quote}`);
 const event={booking_id:+req.params.id,status:'ACCEPTED',operator_type:operatorType,driver_name:operatorType==='DRIVER'?driverName:null,driver_phone:operatorType==='DRIVER'?driverPhone:null,final_amount:quoteAmount};
 emitBooking(req.params.id,'booking_accepted',event);
 res.json({id:+req.params.id,status:'ACCEPTED',...event});
}));
const transitions={reject:['REQUESTED','REJECTED'],cancel:['REQUESTED','CANCELLED'], 'start-journey':['ACCEPTED','OWNER_EN_ROUTE'],arrived:['OWNER_EN_ROUTE','ARRIVED'],'start-service':['ARRIVED','SERVICE_STARTED'],'complete-service':['SERVICE_STARTED','PAYMENT_PENDING']};
for(const [action,[from,to]] of Object.entries(transitions)){router.patch(`/bookings/:id/${action}`,authenticate,asyncRoute(async(req,res)=>{const b=await bookingFor(req.params.id,req.user);const ownerActions=['accept','reject','start-journey','arrived','start-service','complete-service'].includes(action);if(ownerActions&&req.user.id!==b.owner_id||action==='cancel'&&req.user.id!==b.farmer_id)return res.status(403).json({error:'You cannot change this booking.'});if(b.status!==from)return res.status(409).json({error:`This action is not available while booking is ${b.status}.`});let reason=req.body.reason||null;if(action==='reject'&&!reason)return res.status(400).json({error:'Add a short reason for rejecting this request.'});await query('UPDATE bookings SET status=?, rejection_reason=IF(?="REJECTED",?,rejection_reason),cancellation_reason=IF(?="CANCELLED",?,cancellation_reason),final_amount=IF(?="PAYMENT_PENDING",COALESCE(final_amount,estimated_amount),final_amount) WHERE id=?',[to,to,reason,to,reason,to,req.params.id]);if(action==='accept')await query('INSERT IGNORE INTO service_sessions(booking_id,owner_id) VALUES(?,?)',[req.params.id,req.user.id]);const stamps={'start-journey':'started_at',arrived:'arrived_at','start-service':'service_started_at','complete-service':'service_completed_at'};if(stamps[action])await query(`UPDATE service_sessions SET ${stamps[action]}=NOW() WHERE booking_id=?`,[req.params.id]);if(to==='PAYMENT_PENDING')await query('INSERT IGNORE INTO payments(booking_id,amount,status) VALUES(?,?,?)',[req.params.id,b.final_amount||b.estimated_amount,'PENDING']);await notify(action==='cancel'?b.owner_id:b.farmer_id,req.params.id,`booking_${to.toLowerCase()}`,`Booking ${to.replaceAll('_',' ')}`,`Booking #${req.params.id} is now ${to.replaceAll('_',' ').toLowerCase()}.`);emitBooking(req.params.id,`booking_${to.toLowerCase()}`,{booking_id:+req.params.id,status:to});res.json({id:+req.params.id,status:to});}));}
router.post('/bookings/:id/start-journey',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const b=await bookingFor(req.params.id,req.user);if(b.status!=='ACCEPTED')return res.status(409).json({error:'Only accepted bookings can start a journey.'});await query("UPDATE bookings SET status='OWNER_EN_ROUTE' WHERE id=?",[req.params.id]);await query('UPDATE service_sessions SET started_at=NOW() WHERE booking_id=?',[req.params.id]);const operator=b.operator_type==='DRIVER'?`Driver ${b.driver_name}`:'The equipment owner';await notify(b.farmer_id,req.params.id,'operator_en_route','Your operator is on the way',`${operator} started the journey to your field.`);emitBooking(req.params.id,'operator_en_route',{status:'OWNER_EN_ROUTE',operator_type:b.operator_type,driver_name:b.driver_name});res.json({status:'OWNER_EN_ROUTE'});}));
router.post('/bookings/:id/arrived',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const b=await bookingFor(req.params.id,req.user);if(b.status!=='OWNER_EN_ROUTE')return res.status(409).json({error:'Journey has not started.'});await query("UPDATE bookings SET status='ARRIVED' WHERE id=?",[req.params.id]);await query('UPDATE service_sessions SET arrived_at=NOW() WHERE booking_id=?',[req.params.id]);emitBooking(req.params.id,'owner_arrived',{status:'ARRIVED'});res.json({status:'ARRIVED'});}));
router.post('/bookings/:id/start-service',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const b=await bookingFor(req.params.id,req.user);if(b.status!=='ARRIVED')return res.status(409).json({error:'Mark arrival before starting service.'});await query("UPDATE bookings SET status='SERVICE_STARTED' WHERE id=?",[req.params.id]);await query('UPDATE service_sessions SET service_started_at=NOW() WHERE booking_id=?',[req.params.id]);emitBooking(req.params.id,'service_started',{status:'SERVICE_STARTED'});res.json({status:'SERVICE_STARTED'});}));
router.post('/bookings/:id/complete-service',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const b=await bookingFor(req.params.id,req.user);if(b.status!=='SERVICE_STARTED')return res.status(409).json({error:'Start the service first.'});await query("UPDATE bookings SET status='PAYMENT_PENDING' WHERE id=?",[req.params.id]);await query('UPDATE service_sessions SET service_completed_at=NOW() WHERE booking_id=?',[req.params.id]);await query('INSERT IGNORE INTO payments(booking_id,amount,status) VALUES(?,?,?)',[req.params.id,b.final_amount||b.estimated_amount,'PENDING']);await notify(b.farmer_id,req.params.id,'payment_pending','Payment pending','The service is complete. Arrange payment directly with the equipment owner.');emitBooking(req.params.id,'service_completed',{status:'PAYMENT_PENDING'});res.json({status:'PAYMENT_PENDING'});}));
router.post('/bookings/:id/location',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const b=await bookingFor(req.params.id,req.user);if(b.operator_type==='DRIVER')return res.status(409).json({error:'Live location from a driver account is not available. The farmer has the assigned driver’s contact details.'});if(!['OWNER_EN_ROUTE','ARRIVED'].includes(b.status)||!validCoords(req.body.latitude,req.body.longitude))return res.status(400).json({error:'Location updates require an active journey and valid coordinates.'});await query('INSERT INTO location_updates(booking_id,owner_id,latitude,longitude) VALUES(?,?,?,?)',[req.params.id,req.user.id,req.body.latitude,req.body.longitude]);const point={booking_id:+req.params.id,latitude:+req.body.latitude,longitude:+req.body.longitude,at:new Date()};emitBooking(req.params.id,'location_update',point);res.status(202).json({received:true});}));
