router.get('/payments',authenticate,asyncRoute(async(req,res)=>{let sql='SELECT p.*,b.farmer_id,b.owner_id,b.status booking_status,e.brand,e.model FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN equipment e ON e.id=b.equipment_id',args=[];if(req.user.role==='FARMER'){sql+=' WHERE b.farmer_id=?';args.push(req.user.id)}else if(req.user.role==='OWNER'){sql+=' WHERE b.owner_id=?';args.push(req.user.id)}res.json(await query(sql+' ORDER BY p.created_at DESC',args));}));
router.post('/payments',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const {booking_id,method,notes}=req.body;if(!['CASH','OTHER_MANUAL'].includes(method))return res.status(400).json({error:'Only CASH and OTHER_MANUAL are supported.'});const b=await bookingFor(booking_id,req.user);if(b.status!=='PAYMENT_PENDING')return res.status(409).json({error:'Payment can only be recorded after service completion.'});await query("UPDATE payments SET status='PAID',method=?,received_by=?,notes=?,paid_at=NOW(),amount=COALESCE(?,amount) WHERE booking_id=? AND status='PENDING'",[method,req.user.id,notes||null,req.body.amount||null,booking_id]);await query("UPDATE bookings SET status='COMPLETED' WHERE id=? AND status='PAYMENT_PENDING'",[booking_id]);await query('UPDATE service_sessions SET ended_at=NOW() WHERE booking_id=?',[booking_id]);await notify(b.farmer_id,booking_id,'payment_paid','Manual payment recorded',`The owner recorded ${method==='CASH'?'cash':'other manual'} payment.`);emitBooking(booking_id,'booking_completed',{status:'COMPLETED'});res.json({status:'COMPLETED',method});}));
router.post('/bookings/:id/payments',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{req.body.booking_id=req.params.id;if(!req.body.method)req.body.method='CASH';const {booking_id,method,notes}=req.body;if(!['CASH','OTHER_MANUAL'].includes(method))return res.status(400).json({error:'Only CASH and OTHER_MANUAL are supported.'});const b=await bookingFor(booking_id,req.user);if(b.status!=='PAYMENT_PENDING')return res.status(409).json({error:'Payment can only be recorded after service completion.'});await query("UPDATE payments SET status='PAID',method=?,received_by=?,notes=?,paid_at=NOW() WHERE booking_id=? AND status='PENDING'",[method,req.user.id,notes||null,booking_id]);await query("UPDATE bookings SET status='COMPLETED' WHERE id=? AND status='PAYMENT_PENDING'",[booking_id]);await query('UPDATE service_sessions SET ended_at=NOW() WHERE booking_id=?',[booking_id]);await notify(b.farmer_id,booking_id,'payment_paid','Manual payment recorded',`The owner recorded ${method==='CASH'?'cash':'other manual'} payment.`);emitBooking(booking_id,'booking_completed',{status:'COMPLETED'});res.json({status:'COMPLETED',method});}));
router.patch('/payments/:id/mark-paid',authenticate,allow('OWNER'),asyncRoute(async(req,res)=>{const method=req.body.method||'CASH';if(!['CASH','OTHER_MANUAL'].includes(method))return res.status(400).json({error:'Only CASH and OTHER_MANUAL are supported.'});const p=(await query('SELECT booking_id FROM payments WHERE id=?',[req.params.id]))[0];if(!p)return res.status(404).json({error:'Payment not found.'});const b=await bookingFor(p.booking_id,req.user);if(b.status!=='PAYMENT_PENDING')return res.status(409).json({error:'Payment is not pending.'});const paid=await query("UPDATE payments SET status='PAID',method=?,received_by=?,paid_at=NOW() WHERE id=? AND status='PENDING'",[method,req.user.id,req.params.id]);if(!paid.affectedRows)return res.status(409).json({error:'This payment was recorded already.'});const completed=await query("UPDATE bookings SET status='COMPLETED' WHERE id=? AND status='PAYMENT_PENDING'",[p.booking_id]);if(!completed.affectedRows)return res.status(409).json({error:'The booking is no longer awaiting payment.'});await query('UPDATE service_sessions SET ended_at=NOW() WHERE booking_id=?',[p.booking_id]);await notify(b.farmer_id,p.booking_id,'payment_paid','Manual payment recorded','The owner recorded '+(method==='CASH'?'cash':'other manual')+' payment.');emitBooking(p.booking_id,'booking_completed',{status:'COMPLETED'});res.json({status:'COMPLETED',method});}));
