router.get('/admin/stats',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>{const result={};for(const [k,s] of Object.entries({users:'SELECT COUNT(*) n FROM users',farmers:"SELECT COUNT(*) n FROM users WHERE role='FARMER'",owners:"SELECT COUNT(*) n FROM users WHERE role='OWNER'",equipment:'SELECT COUNT(*) n FROM equipment',verified_equipment:"SELECT COUNT(*) n FROM equipment WHERE verification_status='VERIFIED'",pending_equipment:"SELECT COUNT(*) n FROM equipment WHERE verification_status='PENDING_VERIFICATION'",rejected_equipment:"SELECT COUNT(*) n FROM equipment WHERE verification_status='REJECTED'",bookings:'SELECT COUNT(*) n FROM bookings',active_bookings:"SELECT COUNT(*) n FROM bookings WHERE status IN ('ACCEPTED','OWNER_EN_ROUTE','ARRIVED','SERVICE_STARTED')",completed_bookings:"SELECT COUNT(*) n FROM bookings WHERE status='COMPLETED'",cancelled_bookings:"SELECT COUNT(*) n FROM bookings WHERE status='CANCELLED'",manual_payments:"SELECT COUNT(*) n FROM payments WHERE status='PAID'",open_disputes:"SELECT COUNT(*) n FROM disputes WHERE status IN ('OPEN','UNDER_REVIEW')"}))result[k]=(await query(s))[0].n;res.json(result);}));
