router.patch('/admin/users/:id/status',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>{const active=req.body.is_active===true||req.body.is_active===1||req.body.is_active==='1';if(![true,false,0,1,'0','1'].includes(req.body.is_active))return res.status(400).json({error:'Choose an active or inactive status.'});if(String(req.params.id)===String(req.user.id)&&!active)return res.status(400).json({error:'You cannot deactivate your own admin account.'});const result=await query('UPDATE users SET is_active=? WHERE id=?',[active?1:0,req.params.id]);if(!result.affectedRows)return res.status(404).json({error:'User not found.'});res.json({id:+req.params.id,is_active:active});}));
router.get('/admin/equipment',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>res.json(await query(`SELECT e.*,u.name owner_name,u.phone owner_phone FROM equipment e JOIN users u ON u.id=e.owner_id WHERE (?='' OR e.verification_status=?) ORDER BY e.created_at DESC`,[req.query.status||'',req.query.status||'']))));
router.get('/admin/equipment/:id/documents',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>res.json(await query('SELECT id,equipment_id,document_type,original_name,uploaded_at FROM equipment_documents WHERE equipment_id=? ORDER BY uploaded_at DESC',[req.params.id]))));
router.get('/admin/equipment/:id/documents/:documentId',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>{
 const doc=(await query('SELECT storage_key,original_name FROM equipment_documents WHERE id=? AND equipment_id=?',[req.params.documentId,req.params.id]))[0];
 if(!doc)return res.status(404).json({error:'Verification document not found.'});
 const filePath=path.resolve(privateDocumentRoot,doc.storage_key);
 if(!filePath.startsWith(`${privateDocumentRoot}${path.sep}`))return res.status(400).json({error:'Invalid document path.'});
 const contents=await readFile(filePath);
 const extension=path.extname(filePath).toLowerCase();
 const mimeType={'.pdf':'application/pdf','.jpg':'image/jpeg','.png':'image/png','.webp':'image/webp'}[extension]||'application/octet-stream';
 res.setHeader('Content-Type',mimeType);
  const originalName=path.basename(doc.original_name||'verification-document').replace(/[\r\n\0]/g,'').slice(0,255);
  res.setHeader('Content-Disposition',`inline; filename="verification-document${extension}"; filename*=UTF-8''${encodeURIComponent(originalName)}`);
 res.send(contents);
}));
router.patch('/admin/equipment/:id/approve',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>{
 const equipment=(await query('SELECT id,owner_id,registration_number FROM equipment WHERE id=?',[req.params.id]))[0];
 if(!equipment)return res.status(404).json({error:'Equipment listing not found.'});
 if(equipment.registration_number){const certificate=(await query("SELECT id FROM equipment_documents WHERE equipment_id=? AND document_type='REGISTRATION_CERTIFICATE' LIMIT 1",[req.params.id]))[0];if(!certificate)return res.status(409).json({error:'Review the registration certificate before verifying this registered equipment.'});}
 await query("UPDATE equipment SET verification_status='VERIFIED',registration_status=IF(registration_number IS NULL,'NOT_REQUIRED','VERIFIED') WHERE id=?",[req.params.id]);
 await notify(equipment.owner_id,null,'equipment_verification','Equipment verified','Your equipment listing has been verified and can now appear in farmer search.');
 res.json({status:'VERIFIED'});
}));
router.patch('/admin/equipment/:id/reject',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>{
 const result=await query("UPDATE equipment SET verification_status='REJECTED',registration_status=IF(registration_number IS NULL,registration_status,'REJECTED') WHERE id=?",[req.params.id]);
 if(!result.affectedRows)return res.status(404).json({error:'Equipment listing not found.'});
 const equipment=(await query('SELECT owner_id FROM equipment WHERE id=?',[req.params.id]))[0];
 await notify(equipment.owner_id,null,'equipment_verification','Equipment needs changes','Your equipment listing was not approved. Review the details and contact Agriiigo support.');
 res.json({status:'REJECTED'});
}));
for(const [path,status] of [['approve','VERIFIED'],['reject','REJECTED']])router.patch(`/admin/equipment/:id/${path}`,authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>{const r=await query('UPDATE equipment SET verification_status=? WHERE id=?',[status,req.params.id]);if(r.affectedRows)await notify((await query('SELECT owner_id FROM equipment WHERE id=?',[req.params.id]))[0].owner_id,null,'equipment_verification',`Equipment ${status.toLowerCase()}`,`Your equipment listing is ${status.toLowerCase()}.`);res.json({status});}));
router.get('/admin/bookings',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>res.json(await query(`SELECT b.*,f.name farmer_name,o.name owner_name,e.brand,e.model,s.name service_name FROM bookings b JOIN users f ON f.id=b.farmer_id JOIN users o ON o.id=b.owner_id JOIN equipment e ON e.id=b.equipment_id JOIN services s ON s.id=b.service_id ORDER BY b.created_at DESC LIMIT 500`))));
router.get('/admin/payments',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>res.json(await query('SELECT p.*,b.farmer_id,b.owner_id,b.status booking_status FROM payments p JOIN bookings b ON b.id=p.booking_id ORDER BY p.created_at DESC LIMIT 500'))));
router.get('/admin/disputes',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>res.json(await query('SELECT d.*,b.status booking_status,f.name farmer_name,o.name owner_name FROM disputes d JOIN bookings b ON b.id=d.booking_id JOIN users f ON f.id=b.farmer_id JOIN users o ON o.id=b.owner_id ORDER BY d.created_at DESC'))));
router.get('/admin/reviews',authenticate,allow('ADMIN'),asyncRoute(async(req,res)=>res.json(await query('SELECT r.*,u.name reviewer_name,t.name reviewed_name FROM reviews r JOIN users u ON u.id=r.reviewer_id JOIN users t ON t.id=r.reviewed_user_id ORDER BY r.created_at DESC'))));
